\set ON_ERROR_STOP on
begin;
select no_plan();
select is((select count(*)::integer from pg_class where relname in ('inventory_sale_orders','inventory_sale_payment_entries','inventory_warranty_versions','inventory_sales_command_ledger') and relrowsecurity),4,'all four sales tables have RLS');
select ok(not has_table_privilege('authenticated','public.inventory_sale_orders','select'),'browser no direct sales SELECT');
select ok(not has_table_privilege('service_role','public.inventory_sale_orders','insert,update,delete'),'service has RPC-only writes');
select ok(not has_function_privilege('anon','public.repairdesk_inventory_sales_command(uuid,uuid,text,uuid,jsonb)','execute'),'anon no RPC');
select ok(not has_function_privilege('authenticated','public.repairdesk_inventory_sales_read(uuid,uuid,text,uuid,text,uuid,text)','execute'),'authenticated no read RPC');
select ok(has_function_privilege('service_role','public.repairdesk_inventory_sales_command(uuid,uuid,text,uuid,jsonb)','execute'),'enable grants service RPC');
insert into public.synthetic_requests values('create',gen_random_uuid(),public.synthetic_sales_payload(1),null);
set local role service_role;
update public.synthetic_requests set result=public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',key,payload) where name='create';
reset role;
select is((select result->>'code' from public.synthetic_requests where name='create'),'completed','partial creation succeeds through service RPC');
select is((select status from public.inventory_sale_orders where inventory_item_id=public.synthetic_item_id(1)),'awaiting_payment','partial payment retains device');
select is((select count(*)::integer from public.inventory_warranty_versions),0,'payment does not start warranty');
select is((select count(*)::integer from public.inventory_stock_movements where movement_type='sell'),0,'payment does not deliver stock');
select is((select sum(amount) from public.inventory_transactions where item_id=public.synthetic_item_id(1)),30::numeric,'compatible money transaction exactly once');
select is((select balance_after_cents from public.inventory_sale_payment_entries limit 1),7000::bigint,'payment stores immutable historical balance');
select is((select public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',key,payload)->>'code' from public.synthetic_requests where name='create'),'idempotent_replay','same request replay');
select is((select public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',key,payload||'{"price_cents":20000}'::jsonb)->>'code' from public.synthetic_requests where name='create'),'idempotency_conflict','different request same key refused');
select is(public.synthetic_sales_call(1,'sale.create')->>'code','already_sold','second sale refused');
select is(public.synthetic_sales_call(1,'pickup.confirm')->>'code','balance_remaining','all roles must pay before delivery');
select is(public.synthetic_sales_call(1,'payment.append',8000)->>'code','overpayment','overpayment refused');
select throws_ok($$select public.repairdesk_complete_inventory_sale_v2('10000000-0000-4000-8000-000000000001',public.synthetic_item_id(1),'20000000-0000-4000-8000-000000000001',(select updated_at from inventory_items where id=public.synthetic_item_id(1)),gen_random_uuid(),'30000000-0000-4000-8000-000000000001',100,100,'cash','store',24,'{}','pending',null,'2024-02-29T11:00:00Z')$$,'23514',null,'unchanged old full-sale RPC cannot steal reserved item');
select throws_ok($$insert into public.inventory_transactions(id,store_id,item_id,transaction_type,amount,method,actor_id,created_at) values(gen_random_uuid(),'10000000-0000-4000-8000-000000000001',public.synthetic_item_id(1),'sale_payment',70,'cash','20000000-0000-4000-8000-000000000001',now())$$,'23514',null,'old direct payment cannot bypass new ledger');
select is(public.synthetic_sales_call(1,'payment.append',7000)->>'status','paid_pending_pickup','full balance can remain in store');
select is((select count(*)::integer from inventory_warranty_versions),0,'paid but held has no warranty');
select is(public.synthetic_sales_call(1,'pickup.confirm')->>'status','delivered','fully paid pickup succeeds');
select is((select count(*)::integer from inventory_stock_movements where movement_type='sell'),1,'exactly one stock sell movement');
select is((select ends_on::text from inventory_warranty_versions limit 1),'2026-02-28','leap-day clamp uses Rome business calendar');
select is((select starts_at from inventory_warranty_versions limit 1),'2024-02-29T11:00:00Z'::timestamptz,'warranty starts at physical delivery');
select is((select public.repairdesk_inventory_sales_read('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','receipt',o.id,'payment',p.id,null)->'data'->'order'->>'balance_cents' from inventory_sale_orders o join inventory_sale_payment_entries p on p.sale_order_id=o.id where p.sequence=1 and o.inventory_item_id=public.synthetic_item_id(1)),'7000','historical receipt keeps balance after original payment');
select is((select public.repairdesk_inventory_sales_read('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','receipt',o.id,'payment',p.id,null)->'data'->'order'->'delivered_at' from inventory_sale_orders o join inventory_sale_payment_entries p on p.sale_order_id=o.id where p.sequence=1 and o.inventory_item_id=public.synthetic_item_id(1)),'null'::jsonb,'historical receipt never gets current delivery');
select throws_ok($$update public.inventory_sale_payment_entries set amount_cents=1$$,'23514',null,'payments append-only');
select throws_ok($$delete from public.inventory_warranty_versions$$,'23514',null,'warranty append-only');
select throws_ok($$update public.inventory_sales_command_ledger set response='{}'$$,'23514',null,'idempotency ledger immutable');
select throws_ok($$insert into public.inventory_sale_orders select (jsonb_populate_record(null::public.inventory_sale_orders,to_jsonb(o)||jsonb_build_object('id',gen_random_uuid(),'store_id','10000000-0000-4000-8000-000000000002'))).* from public.inventory_sale_orders o limit 1$$,'23503',null,'composite FK prevents cross-store unit and customer');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','sale.create',gen_random_uuid(),public.synthetic_sales_payload(2))->>'code','actor_forbidden','technician cannot collect or sell');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000005','sale.create',gen_random_uuid(),public.synthetic_sales_payload(2))->>'code','actor_forbidden','viewer cannot sell');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000006','sale.create',gen_random_uuid(),public.synthetic_sales_payload(2))->>'code','actor_forbidden','inactive membership cannot sell');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','sale.create',gen_random_uuid(),public.synthetic_sales_payload(2))->>'code','actor_forbidden','actor cannot select another store');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',gen_random_uuid(),public.synthetic_sales_payload(2)||'{"customer_id":"30000000-0000-4000-8000-000000000002"}'::jsonb)->>'code','customer_not_found','cross-store customer refused');
select is(public.repairdesk_inventory_sales_read('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','receipt',(select id from inventory_sale_orders limit 1),'sale')->>'code','actor_forbidden','output denied before PII projection');
grant select on public.inventory_sale_orders to authenticated;
set local role authenticated;
select is((select count(*)::integer from public.inventory_sale_orders),0,'RLS denies rows even if SELECT accidentally granted');
reset role;
select is(public.synthetic_sales_call(2,'sale.create',10000,true)->>'status','delivered','single full payment and delivery atomic');
select is(public.synthetic_sales_call(3,'sale.create',3000,true)->>'code','balance_remaining','underpaid atomic delivery rejected entirely');
select is((select count(*)::integer from inventory_sale_orders where inventory_item_id=public.synthetic_item_id(3)),0,'failed atomic command has no order');
select is(public.synthetic_sales_call(3,'sale.create',0)->>'code','invalid_amount','zero initial payment refused');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',gen_random_uuid(),jsonb_set(public.synthetic_sales_payload(3),'{payment,amount_cents}','1.1'))->>'code','invalid_amount','fractional cents refused');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',gen_random_uuid(),public.synthetic_sales_payload(3)||'{"expected_unit_version":999}'::jsonb)->>'code','stale_version','unit CAS');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',gen_random_uuid(),public.synthetic_sales_payload(3)||'{"expected_item_updated_at":"2020-01-01T00:00:00Z"}'::jsonb)->>'code','stale_version','item CAS');
update inventory_items set status='intake',imei_check_status='unchecked',activation_lock_status='unchecked',data_wipe_status='unchecked',functional_grade='untested' where id=public.synthetic_item_id(3);
select is(public.synthetic_sales_call(3)->>'code','inspection_blocked','quick-create intake never becomes an implicit pass');
select ok(jsonb_array_length(public.repairdesk_inventory_sales_read('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','summary',public.synthetic_item_id(3))->'data'->'inspection_missing')>=5,'read reports actual inspection deficiencies');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',gen_random_uuid(),public.synthetic_sales_payload(4)||'{"warranty_months":12}'::jsonb)->>'code','invalid_warranty','12 month warranty needs express consent');
select is(public.repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',gen_random_uuid(),public.synthetic_sales_payload(4,'sale.create',10000,true)||'{"warranty_months":12,"shortening_agreed":true,"shortening_agreed_at":"2024-02-28T10:00:00Z"}'::jsonb)->>'code','completed','used-device 12 month explicit agreement accepted');
select is((select ends_on::text from inventory_warranty_versions where sale_order_id=(select id from inventory_sale_orders where inventory_item_id=public.synthetic_item_id(4))),'2025-02-28','12 month anniversary clamps leap day');
-- Fault injection after all financial writes: whole command, revision, ledger and stock roll back.
create function public.synthetic_fail_event() returns trigger language plpgsql as $$ begin raise exception using errcode='23514',message='synthetic fault'; end $$;
create trigger synthetic_fail_event before insert on public.inventory_events for each row execute function public.synthetic_fail_event();
insert into public.synthetic_requests(name,result) values('before-fault',jsonb_build_object('revision',(select version from repairdesk_store_domain_versions where store_id='10000000-0000-4000-8000-000000000001' and domain='inventory')));
select is(public.synthetic_sales_call(5,'sale.create',10000,true)->>'code','invariant_failed','late fault returns failure');
select is((select count(*)::integer from inventory_sale_orders where inventory_item_id=public.synthetic_item_id(5)),0,'late fault leaves no order');
select is((select count(*)::integer from inventory_transactions where item_id=public.synthetic_item_id(5)),0,'late fault leaves no payment');
select is((select version from repairdesk_store_domain_versions where store_id='10000000-0000-4000-8000-000000000001' and domain='inventory'),(select (result->>'revision')::bigint from synthetic_requests where name='before-fault'),'rollback leaves revision unchanged');
select is((select status from inventory_stock_units where legacy_inventory_item_id=public.synthetic_item_id(5)),'listed','rollback leaves stock in place');
drop trigger synthetic_fail_event on public.inventory_events;
select * from finish();
rollback;
